                marks.setdefault(r, []).append(mk)
            recs.append((o['contest'], marks))
    else:
        i = 0
        while i < len(lines):
            ln = lines[i].rstrip('\r')
            if ln.strip() == '' or ln.startswith('#'):
                m = re.match(r'#\s*([^:]+?)\s*:\s*(.*?)\s*$', ln)
                if m:
                    meta[m.group(1).strip().lower()] = m.group(2)
                i += 1
                continue
            break
        body = '\n'.join(l for l in lines[i:])
        rd = csv.reader(io.StringIO(body, newline=''))
        header = None
        for row in rd:
            if not row or all(not c.strip() for c in row):
                continue
            if header is None:
                header = [c.strip() for c in row]
                continue
            d = dict(zip(header, row))
            marks = {}
            for h, v in d.items():
                m = re.fullmatch(r'rank(\d+)', h)
                if not m or v is None or v == '':
                    continue
                r = int(m.group(1))
                for part in v.split('|'):
                    if part == '':
                        continue
                    if part.startswith('WI:'):
                        marks.setdefault(r, []).append(('w', part[3:]))
                    else:
                        marks.setdefault(r, []).append(('c', part))
            recs.append((d['contest'], marks))
    return meta, recs


def load_records(indir):
    cvr = os.path.join(indir, 'cvr')
    best = {}
    for name in os.listdir(cvr):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p) or not (name.endswith('.csv') or name.endswith('.jsonl')):
            continue
        meta, recs = read_batch(p)
        b = str(meta['batch'])
        rev = int(str(meta['revision']).strip())
        st = str(meta.get('status', 'final')).strip().lower()
        if b not in best or rev > best[b][0]:
            best[b] = (rev, st, recs)
