            if i + 1 >= n or rankings[i + 1][0] == 'skip':
                return None
        elif t == 'over':
            if OVERVOTE_SKIPPED and (i + 1 >= n or rankings[i + 1][0] == 'skip'):
                return None
    return None


def run_contest(contest, records):
