            withdrawn.add(norm_id(c['id']))
    wi_map = {}
    for w in contest.get('write_ins', []):
        orig[norm_id(w['id'])] = w['id']
        for t in [w['name']] + list(w.get('aliases', [])):
            wi_map[norm_text(t)] = norm_id(w['id'])
    continuing = [c for c in orig if c not in withdrawn]
    lot = [norm_id(x) for x in contest.get('lot_order', [])]
    ballots = [read_ballot(m, contest['max_ranks'], orig, withdrawn, wi_map) for m in records]
    total = len(ballots)
    rounds, history, winner = [], [], None
    cont = set(continuing)
    rn = 0
    while True:
        rn += 1
        tal = {c: 0 for c in cont}
        for b in ballots:
            c = resolve(b, cont)
            if c is not None:
                tal[c] += 1
        active = sum(tal.values())
        history.append(tal)
        entry = {'round': rn, 'tallies': {orig[c]: v for c, v in tal.items()},
                 'exhausted': total - active, 'eliminated': []}
        rounds.append(entry)
        if active == 0 or not cont:
            break
        win = None
        for c, v in tal.items():
            if v * 2 > active:
                win = c
        if win is None and len(cont) == 1:
            win = next(iter(cont))
        if win is not None:
            winner = orig[win]
            break
        zeros = [c for c in cont if tal[c] == 0]
        if zeros:
            elim = zeros
        else:
            m = min(tal.values())
            tied = [c for c in cont if tal[c] == m]
            k = len(history) - 2
            while len(tied) > 1 and k >= 0:
                mm = min(history[k][c] for c in tied)
                tied = [c for c in tied if history[k][c] == mm]
                k -= 1
            if len(tied) > 1:
                tied.sort(key=lambda c: lot.index(c) if c in lot else -1)
                tied = [tied[-1]]
            elim = tied
        entry['eliminated'] = sorted(orig[c] for c in elim)
        cont -= set(elim)
    return {'contest': contest['id'], 'ballots': total, 'winner': winner, 'rounds': rounds}


def main():
    indir, outfile = sys.argv[1], sys.argv[2]
    with open(os.path.join(indir, 'election.json'), encoding='utf-8') as f:
        el = json.load(f)
    recs = load_records(indir)
    by = {}
    for cid, marks in recs:
        by.setdefault(cid, []).append(marks)
    out = {'election': el['election'],
           'contests': [run_contest(c, by.get(c['id'], [])) for c in el['contests']]}
    with open(outfile, 'w', encoding='utf-8') as f:
        json.dump(out, f, ensure_ascii=False, indent=1)


